        static float[] DungeonMeleeLineSamples(string npc, string state) {
            switch (npc) {
                case "NUI_NASOD_MINER_THIN": return state == "NASOD_MINER_THIN_ATTACK_A" ? NasodMinerThinLines : null;
                case "NUI_NASOD_MINER_THIN_AIR": return state == "NASOD_MINER_THIN_AIR_ATTACK_A" ? NasodMinerThinLines : null;
                case "NUI_NASOD_MINER_THIN_DEFECT": return state == "NASOD_MINER_THIN_DEFECT_ATTACK_A" ? NasodMinerThinDefectLines : null;
                case "NUI_NASOD_MINER_THIN_DEFECT_DIE": return state == "NASOD_MINER_THIN_DEFECT_DIE_ATTACK_A" ? NasodMinerThinDefectDieLines : null;
                case "NUI_AIRSHIP_SOLDIER_SWORDMAN": return state == "AIRSHIP_SOLDIER_SWORDMAN_ATTACK_A" ? AirshipSoldierSwordmanLines : null;
                case "NUI_AIRSHIP_SOLDIER_REPAIRMAN": return state == "AIRSHIP_SOLDIER_REPAIRMAN_ATTACK_A" ? AirshipSoldierRepairmanLines : null;
                default: return null;
            }
        }
